import{_ as t,o as _,c as a,ac as r}from"./chunks/framework.B-3EzaJq.js";const m=JSON.parse('{"title":"党的十一届七中全会给蔡畅同志的致敬信","description":"","frontmatter":{"prev":{"text":"党的十一届七中全会给刘伯承同志的致敬信","link":"./党的十一届七中全会给刘伯承同志的致敬信"},"next":{"text":"在党的十一届七中全会闭幕时的讲话","link":"./在党的十一届七中全会闭幕时的讲话"}},"headers":[],"relativePath":"11/7/党的十一届七中全会给蔡畅同志的致敬信.md","filePath":"11/7/党的十一届七中全会给蔡畅同志的致敬信.md"}'),p={name:"11/7/党的十一届七中全会给蔡畅同志的致敬信.md"};function s(n,e,o,i,c,d){return _(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="党的十一届七中全会给蔡畅同志的致敬信" tabindex="-1">党的十一届七中全会给蔡畅同志的致敬信 <a class="header-anchor" href="#党的十一届七中全会给蔡畅同志的致敬信" aria-label="Permalink to &quot;党的十一届七中全会给蔡畅同志的致敬信&quot;">​</a></h1><p><em>（一九八二年八月六日）</em></p><p>敬爱的蔡畅同志：</p><p>  我们，正在举行中国共产党第十一届中央委员会第七次全体会议的同志，谨以全会的名义，向您致以亲切的问候和崇高的敬意！</p><p>  您从一九一九年就投身革命，是我国妇女运动的杰出领导者和国际进步妇女运动的著名活动家。您在我国革命的各个历史时期，总是站在斗争的前列，特别致力于党领导下的妇女解放事业，坚持妇女运动的正确方向。全国解放以前，您为了发动和组织妇女推翻帝国主义、封建主义、官僚资本主义“三座大山”，使我国人民特别是妇女从重重压迫下解放出来，出生入死，奋不顾身。您带领妇女群众建设革命根据地，发展生产，支援战争，作出了巨大的贡献。建国以后，您长期担任全国妇女联合会的主要领导职务，为发动和组织妇女参加社会主义的革命和建设，为维护妇女儿童的切身利益，付出了全部的心力。中国人民特别是中国妇女，将永远铭记您的历史功绩。</p><p>  您身上表现出的无产阶级革命家的优秀品质，长期以来受到人们的尊敬。无论是在国民党反动派的白色恐怖下，在二万五千里长征的艰难险阻中，在革命根据地的艰苦环境里，您都坚贞不渝。建国以后，尽管您处于高级领导岗位，但始终保持了人民公仆的本色。您的崇高品德教育着千千万万的党员和人民。</p><p>  您是我们党最早的党员之一，多次党代表大会的代表，多届中央委员会的委员。由于年龄和健康状况，您不能再参加即将召开的党的第十二次全国代表大会，也不能继续担任党和国家的领导职务。您的光辉的革命业绩，您的崇高的革命品德，将激励全党广大党员和干部，提高自己的历史责任感，同心同德，奋发图强，为共产主义的远大理想而努力奋斗！</p><p>  衷心祝愿您长寿！</p><div class="sig-block-b"><div class="text-center"><p><strong>中国共产党第十一届<br>中央委员会第七次全体会议</strong><br> 一九八二年八月六日</p></div></div>',9)])])}const f=t(p,[["render",s]]);export{m as __pageData,f as default};
